<?php  use App\Models\ProfilPegawai; use App\Models\User;  beforeEach(function () {     $this->admin = User::factory()->create([         'role' => 'admin',         'status' => 'aktif',     ]); });  test('admin can view pegawai index list', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Budi Santoso',         'jabatan' => 'Admin Gudang',     ]);      $response = $this->actingAs($this->admin)->get(route('admin.pegawai.index'));      $response->assertStatus(200);     $response->assertSee('Budi Santoso'); });  test('admin can search pegawai by name', function () {     ProfilPegawai::create([         'nama' => 'Ahmad Dahlan',         'jabatan' => 'Pengasuh',     ]);     ProfilPegawai::create([         'nama' => 'Siti Aminah',         'jabatan' => 'Bendahara',     ]);      $response = $this->actingAs($this->admin)->get(route('admin.pegawai.index', ['search' => 'Ahmad']));      $response->assertStatus(200);     $response->assertSee('Ahmad Dahlan');     $response->assertDontSee('Siti Aminah'); });  test('admin can view pegawai create page', function () {     $response = $this->actingAs($this->admin)->get(route('admin.pegawai.create'));      $response->assertStatus(200); });  test('admin can create pegawai without user account', function () {     $response = $this->actingAs($this->admin)->post(route('admin.pegawai.store'), [         'nama' => 'Rudi Hartono',         'jabatan' => 'Pengasuh',         'tempat_lahir' => 'Surabaya',         'tanggal_lahir' => '1995-05-10',         'jenis_kelamin' => 'L',         'no_hp' => '081234567890',         'alamat' => 'Jl. Pahlawan No. 1',         'buat_akun_login' => '0',     ]);      $response->assertRedirect(route('admin.pegawai.index'));     $response->assertSessionHas('success');      $this->assertDatabaseHas('profil_pegawai', [         'nama' => 'Rudi Hartono',         'jabatan' => 'Pengasuh',         'user_id' => null,     ]); });  test('admin can create pegawai with user account', function () {     $response = $this->actingAs($this->admin)->post(route('admin.pegawai.store'), [         'nama' => 'Dewi Lestari',         'jabatan' => 'Bendahara',         'tempat_lahir' => 'Jakarta',         'tanggal_lahir' => '1992-08-15',         'jenis_kelamin' => 'P',         'no_hp' => '081234567891',         'alamat' => 'Jl. Merdeka No. 10',         'buat_akun_login' => '1',         'username' => 'dewi_bendahara',         'email' => 'dewi@example.com',         'password' => 'password123',         'password_confirmation' => 'password123',         'role' => 'bendahara',     ]);      $response->assertRedirect(route('admin.pegawai.index'));     $response->assertSessionHas('success');      $this->assertDatabaseHas('users', [         'username' => 'dewi_bendahara',         'email' => 'dewi@example.com',         'role' => 'bendahara',     ]);      $user = User::where('username', 'dewi_bendahara')->first();     $this->assertDatabaseHas('profil_pegawai', [         'nama' => 'Dewi Lestari',         'user_id' => $user->id,     ]); });  test('admin can view pegawai detail', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Hendro Siswanto',         'jabatan' => 'Pengasuh',         'alamat' => 'Jl. Melati No. 5',     ]);      $response = $this->actingAs($this->admin)->get(route('admin.pegawai.show', $pegawai));      $response->assertStatus(200);     $response->assertSee('Hendro Siswanto'); });  test('admin can view pegawai edit page', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Slamet Riyadi',         'jabatan' => 'Pengasuh',     ]);      $response = $this->actingAs($this->admin)->get(route('admin.pegawai.edit', $pegawai));      $response->assertStatus(200);     $response->assertSee('Slamet Riyadi'); });  test('admin can update pegawai profile data', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Bambang Pamungkas',         'jabatan' => 'Pengasuh',     ]);      $response = $this->actingAs($this->admin)->put(route('admin.pegawai.update', $pegawai), [         'nama' => 'Bambang Pamungkas Edit',         'jabatan' => 'Pengasuh Senior',         'no_hp' => '089999999999',     ]);      $response->assertRedirect(route('admin.pegawai.index'));     $response->assertSessionHas('success');      $this->assertDatabaseHas('profil_pegawai', [         'id' => $pegawai->id,         'nama' => 'Bambang Pamungkas Edit',         'jabatan' => 'Pengasuh Senior',     ]); });  test('admin can delete pegawai', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Pegawai Akan Dihapus',         'jabatan' => 'Pengasuh',     ]);      $response = $this->actingAs($this->admin)->delete(route('admin.pegawai.destroy', $pegawai));      $response->assertRedirect(route('admin.pegawai.index'));     $response->assertSessionHas('success');      $this->assertDatabaseMissing('profil_pegawai', [         'id' => $pegawai->id,     ]); });  test('admin cannot delete own linked pegawai account', function () {     $adminPegawai = ProfilPegawai::create([         'user_id' => $this->admin->id,         'nama' => 'Admin Utama',         'jabatan' => 'Admin',     ]);      $response = $this->actingAs($this->admin)->delete(route('admin.pegawai.destroy', $adminPegawai));      $response->assertSessionHas('error');     $this->assertDatabaseHas('profil_pegawai', [         'id' => $adminPegawai->id,     ]); });